import json, time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from urllib import request, error

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END_EXCLUSIVE = datetime(2025, 6, 1, tzinfo=timezone.utc)
token = None

def get_token():
    global token
    while True:
        try:
            with request.urlopen(request.Request(BASE + '/token', data=b'', method='POST'), timeout=15) as resp:
                token = [REDACTED_SECRET]'token']
                return
        except error.HTTPError as e:
            if e.code == 429:
                delay = float(e.headers.get('Retry-After', '1'))
                time.sleep(delay)
                continue
            raise
        except (error.URLError, TimeoutError):
            time.sleep(1)

def api_get(path):
    global token
    attempts = 0
    while True:
        attempts += 1
        if token is None:
            get_token()
        req = request.Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
        try:
            with request.urlopen(req, timeout=15) as resp:
                return json.load(resp)
        except error.HTTPError as e:
            if e.code == 401:
                token = None
                continue
            if e.code == 429:
                delay = float(e.headers.get('Retry-After', '1'))
                time.sleep(delay)
                continue
            if 500 <= e.code < 600 and attempts < 20:
                time.sleep(min(attempts, 5))
                continue
            raise
        except (error.URLError, TimeoutError):
            if attempts >= 20:
                raise
            time.sleep(min(attempts, 5))

seen = set()
duplicates = 0
qualifying = []
page = 1
expected_pages = None
while True:
    data = api_get(f'/orders?page={page}')
    if expected_pages is None:
        expected_pages = int(data['total_pages'])
    elif int(data['total_pages']) "'!= expected_pages:
        raise RuntimeError(f'"'total_pages drift: {expected_pages} -> {data[\"total_pages\"]}')
    if int(data['page']) "'!= page:
        raise RuntimeError(f'"'page mismatch: wanted {page}, got {data[\"page\"]}')
    for order in data['items']:
        oid = order['id']
        if oid in seen:
            duplicates += 1
            continue
        seen.add(oid)
        when = datetime.fromisoformat(order['placed_at'])
        if when.tzinfo is None:
            raise RuntimeError(f'naive timestamp for {oid}')
        when_utc = when.astimezone(timezone.utc)
        if order['status'] == 'shipped' and START <= when_utc < END_EXCLUSIVE:
            qualifying.append(order)
    if data['next'] is None:
        if page "'!= expected_pages:
            raise RuntimeError(f'"'pagination ended at {page} of {expected_pages}')
        break
    page += 1

customers = {}
by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    cid = order['customer_id']
    if cid not in customers:
        customers[cid] = api_get(f'/customers/{cid}')
    customer = customers[cid]
    raw = Decimal(order['amount_cents']) * (Decimal(100) - Decimal(customer['discount_pct'])) / Decimal(100)
    discounted = int(raw.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    by_region[customer['region']] += discounted

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
print(json.dumps(result, indent=2))
print(json.dumps({'pages': expected_pages, 'listings': sum([len(seen), duplicates]), 'distinct_orders': len(seen), 'customers_fetched': len(customers)}, indent=2))
PY"

